import { games,gameById } from './catalog.js';
import { art } from './art.js';
import {createSession} from './session.js';
import {saveResult,browserStorage} from './history.js';
import {showResults,showProgress} from './results.js';
import {formatTime} from './ui.js';
import {shouldHandleSameHash} from './interactions.js';
const main=document.querySelector('main');
const categories=['All games','Memory','Numbers','Spatial','Attention','Work style'];
let filter='All games';
let active=null,mounted=null,routeToken=0,currentHash=location.hash||'#library';
function renderCards(){document.querySelector('#game-grid').innerHTML=games.filter(g=>filter==='All games'||g.category===filter).map(g=>`<a class="game-card" href="#game/${g.id}"><div class="art-panel ${g.category.toLowerCase().replace(' ','-')}">${art(g.id)}<span class="time">${Math.round(g.durationSeconds/60)} min</span></div><div class="card-copy"><span class="category">${g.category}</span><h3>${g.name}</h3><p>${g.description}</p><span class="practice-link">Practice game <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m9 5 7 7-7 7"/></svg></span></div></a>`).join('');}
export function showLibrary(){
 main.innerHTML=`<section class="intro"><div><h1>A little practice.<br>A lot more confidence.</h1><p>Get familiar with the games. Find your rhythm.<br>Make your next attempt your best one.</p></div><aside class="personal-intro"><div class="mini-mark">${art('pulse')}</div><strong>Your pace. Your progress.</strong><p>13 games to explore.<br>No rankings. Just you, getting better.</p></aside></section><section class="featured"><div class="feature-copy"><span class="tag">A good place to start</span><h2>Give your working memory<br>a little workout.</h2><p>Watch. Remember. Repeat. Try Digitspan to get into the flow.</p><a class="primary" href="#game/digitspan">Practice Digitspan</a><span class="feature-meta">3 minutes · Memory</span></div><div class="feature-art">${art('digitspan')}<span>One sequence at a time.</span></div></section><section class="library"><div class="section-heading"><h2>Your practice space</h2><span>13 ways to sharpen your skills</span></div><div class="filters" role="group" aria-label="Filter games">${categories.map(c=>`<button class="filter ${filter===c?'selected':''}" aria-pressed="${filter===c}" data-filter="${c}">${c}</button>`).join('')}</div><div id="game-grid" class="game-grid"></div></section>`;
 renderCards();main.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;showLibrary();main.querySelector(`[data-filter="${filter}"]`).focus();});
}
function instructions(g){main.innerHTML=`<div class="setup"><a class="back" href="#library">All games</a><div class="setup-layout"><div class="setup-art art-panel ${g.category.toLowerCase().replace(' ','-')}">${art(g.id)}</div><div><span class="category">${g.category} · ${Math.round(g.durationSeconds/60)} minute timed practice</span><h1>${g.name}</h1><p class="lead">${g.description}</p><h2>How to play</h2><p>${g.instructions}</p><form id="settings"><fieldset><legend>Choose your pace</legend><div class="mode-options"><label><input type="radio" name="mode" value="learn" checked><span><strong>Learn</strong><small>No time limit. Feedback after each round.</small></span></label><label><input type="radio" name="mode" value="timed"><span><strong>Timed</strong><small>A focused ${Math.round(g.durationSeconds/60)} minute session.</small></span></label></div></fieldset>${g.scored?'<label class="difficulty-label" for="difficulty">Difficulty<select id="difficulty" name="difficulty"><option value="easy">Easy</option><option value="standard" selected>Standard</option><option value="hard">Hard</option></select></label>':'<p class="subtle">Work-style prompts have no difficulty rating or correct answers.</p>'}<button class="primary" type="submit">Start practice</button></form><div class="notice">${g.scored?'Independent practice with original content and practice scoring.':'Your choices are reflections, not scores. No preference is better than another.'}</div></div></div></div>`;main.querySelector('form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.currentTarget);startGame(g,data.get('mode'),data.get('difficulty')||'standard');};}
async function startGame(g,mode,difficulty){const token=++routeToken;main.innerHTML='<div class="empty"><h2>Getting your game ready…</h2></div>';let module;try{module=await import(`./games/${g.id}.js`);}catch{if(token!==routeToken)return;main.innerHTML=`<section class="empty"><h2>This game could not load.</h2><p>Check your connection, then try again.</p><button class="primary" id="retry-load">Try again</button><a class="secondary" href="#library">All games</a></section>`;main.querySelector('#retry-load').onclick=()=>startGame(g,mode,difficulty);return;}if(token!==routeToken)return;
 const metrics={};main.innerHTML=`<section class="session"><div class="session-top"><div><span class="category">${mode==='learn'?'Learning mode':'Timed practice'} · ${difficulty}</span><h1>${g.name}</h1></div><div class="session-clock"><span>${mode==='learn'?'Elapsed':'Remaining'}</span><strong id="clock">${mode==='learn'?'0:00':formatTime(g.durationSeconds)}</strong></div><button id="quit">Leave session</button></div><div class="session-progress"><span id="round-label">Round 1</span><span id="score-label">${g.scored?'0 correct':'0 responses'}</span></div><div class="game-shell" id="game-root"></div><div class="session-bottom"><span>${mode==='learn'?'Take your time. Familiarity comes with practice.':'The timer keeps running if you switch tabs.'}</span>${mode==='learn'?'<button id="finish">Finish practice</button>':''}</div></section>`;
 const session=createSession({mode,durationSeconds:g.durationSeconds,onTick:t=>{const clock=main.querySelector('#clock');if(clock)clock.textContent=formatTime(mode==='learn'?(active?.stats.elapsed||0):Math.ceil(t));},onEnd:stats=>{mounted?.dispose();mounted=null;active=null;const result={...stats,id:crypto.randomUUID(),gameId:g.id,version:g.version,mode,difficulty,timestamp:Date.now(),scored:g.scored,metrics:structuredClone(metrics)};const saved=saveResult(browserStorage(),result);showResults(main,result,saved.warning);window.scrollTo(0,0);main.focus();}});active=session;session.start();const context={session,mode,difficulty,metrics,setRound:(n,total)=>{main.querySelector('#round-label').textContent=`${g.scored?'Round':'Prompt'} ${n}${total?' / '+total:''}`;},updateScore:()=>{main.querySelector('#score-label').textContent=g.scored?`${session.stats.correct} correct / ${session.stats.attempts} answered`:`${session.stats.attempts} responses`;},complete:()=>session.finish()};mounted=module.mountGame(main.querySelector('#game-root'),context);main.querySelector('#quit').onclick=()=>confirmLeave(()=>{disposeGame();instructions(g);});main.querySelector('#finish')?.addEventListener('click',()=>session.finish());window.scrollTo(0,0);main.focus();}
function disposeGame(){routeToken++;active?.dispose();mounted?.dispose();active=null;mounted=null;}
function confirmLeave(action){const d=document.querySelector('#confirm-dialog');if(d.open)return;d.showModal();d.querySelector('[data-stay]').onclick=()=>d.close();d.querySelector('[data-leave]').onclick=()=>{d.close();action();};}
function route(){disposeGame();currentHash=location.hash||'#library';const hash=location.hash.slice(1);document.querySelectorAll('[data-nav]').forEach(a=>a.setAttribute('aria-current',hash==='progress'?(a.dataset.nav==='progress'?'page':'false'):(a.dataset.nav==='library'?'page':'false')));if(hash.startsWith('game/')){const g=gameById(hash.split('/')[1]);g?instructions(g):showLibrary();}else if(hash==='progress')showProgress(main);else showLibrary();window.scrollTo(0,0);}
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#"]');if(link&&!active?.isActive()&&shouldHandleSameHash(link.getAttribute('href'),location.hash)){e.preventDefault();route();return;}if(link&&active?.isActive()&&link.getAttribute('href')!=='#main'){e.preventDefault();const dest=link.getAttribute('href');confirmLeave(()=>{disposeGame();if(location.hash===dest)route();else location.hash=dest;});}});
window.addEventListener('hashchange',()=>{if(active?.isActive()){const dest=location.hash;history.replaceState(null,'',currentHash);confirmLeave(()=>{disposeGame();location.hash=dest;});}else route();});window.addEventListener('beforeunload',e=>{if(active?.isActive()){e.preventDefault();e.returnValue='';}});route();
const modelContext=document.modelContext;if(modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'list_practice_games',description:'List the available practice games and their instructions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>games.map(({id,name,instructions})=>({id,name,instructions}))});register({name:'open_practice_instructions',description:'Open instructions for a game. Does not start a session or create results.',inputSchema:{type:'object',properties:{gameId:{type:'string'}},required:['gameId'],additionalProperties:false},execute:input=>{const g=gameById(input?.gameId);if(!g)throw Error('Unknown game');if(active?.isActive())throw Error('Finish or leave the active session first');history.replaceState(null,'',`#game/${g.id}`);route();return {gameId:g.id,view:'instructions'};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
